import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def _student(last_name, first_name):
    student_id = last_name + first_name
    return Student(student_id, last_name, first_name, "A")

class SeatRowsTests(unittest.TestCase):
    def test_sorts_by_last_name_and_fills_rows(self):
        students = [
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet"),
            _student("Ashby", "Ren"),
            _student("Quill", "Ada")
        ]
        expected = [
            "Row 1: Ashby, Ren | Dunmere, Piet",
            "Row 2: Halloway, Juno | Quill, Ada"
        ]
        self.assertEqual(seat_rows(students, 2), expected)

    def test_last_row_can_be_partial(self):
        students = [
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet"),
            _student("Ashby", "Ren")
        ]
        expected = [
            "Row 1: Ashby, Ren | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ]
        self.assertEqual(seat_rows(students, 2), expected)

    def test_one_row_when_seats_cover_everyone(self):
        students = [
            _student("Quill", "Ada"),
            _student("Ashby", "Ren")
        ]
        expected = ["Row 1: Ashby, Ren | Quill, Ada"]
        self.assertEqual(seat_rows(students, 10), expected)

    def test_ties_on_last_name_sort_by_first_name(self):
        students = [
            _student("Ashby", "Zoe"),
            _student("Ashby", "Ren")
        ]
        expected = ["Row 1: Ashby, Ren | Ashby, Zoe"]
        self.assertEqual(seat_rows(students, 5), expected)

    def test_sorting_ignores_letter_case(self):
        students = [
            _student("Quill", "Ada"),
            _student("ashby", "Ren")
        ]
        expected = ["Row 1: ashby, Ren | Quill, Ada"]
        self.assertEqual(seat_rows(students, 5), expected)

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows([_student("Ashby", "Ren")], 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows([_student("Ashby", "Ren")], -1)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
